const product = items[0].json.product;

// exemplo de catálogo fictício
const catalog = [
  { name: 'Perfume Oud Classic', category: 'arabic', link: 'https://yourshop.com/oud-classic' },
  { name: 'Essência Sândalo Real', category: 'arabic', link: 'https://yourshop.com/sandalo-real' },
  { name: 'Fragrância Ambar do Deserto', category: 'arabic', link: 'https://yourshop.com/ambar-deserto' }
];

const recommendations = catalog.filter(p => p.category === 'arabic' && p.name !== product);

return [{ json: { product, recommendations, clientPhone: "+5511999999999" } }];
